            break;
          }
          case "assistant": {
            const msg = payload.message as { model?: unknown } | undefined;
            if (msg && typeof msg.model === "string") observedModel = msg.model;
            break;
          }
        }
      }

      return {
        runtimeSid,
        yoloMode,
        allowedTools: [...allowedTools],
        lastResultUsage,
        observedModel,
