   * Adapters that need their own HTTP routes (e.g., the CC adapter's
   * /hook/approval endpoint) mount them here. Called once at server startup.
   */
  mountRoutes?(
    app: Hono,
    deps: {
      manager: SessionManager;
      getBunServer: () => import("bun").Server<unknown> | null;
    },
  ): void;

  // --- resume ---

